WITH remaining_keys AS (SELECT country, id FROM customers INTERSECT ALL SELECT country, id FROM customers WHERE signup_date > '2024-08-01'), verified AS (SELECT s.* FROM customers s INNER JOIN remaining_keys k ON s.country = k.country AND s.id = k.id) SELECT name, email, country, city, segment, signup_date, is_active, credit_limit, age, CASE WHEN segment RLIKE '^(Consumer|SMB)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS segment_zone FROM verified ORDER BY country DESC
